package com.lifeos.events; import com.lifeos.events.dto.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/events") public class EventController {private final EventService s;public EventController(EventService s){this.s=s;}@GetMapping public List<EventResponse> list(@AuthenticationPrincipal UserDetails p){return s.list(p.getUsername());}@GetMapping("/{id}") public EventResponse get(@PathVariable Long id,@AuthenticationPrincipal UserDetails p){return s.get(id,p.getUsername());}@PostMapping @ResponseStatus(HttpStatus.CREATED) public EventResponse create(@Valid @RequestBody EventRequest r,@AuthenticationPrincipal UserDetails p){return s.create(r,p.getUsername());}@PutMapping("/{id}") public EventResponse update(@PathVariable Long id,@Valid @RequestBody EventRequest r,@AuthenticationPrincipal UserDetails p){return s.update(id,r,p.getUsername());}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,@AuthenticationPrincipal UserDetails p){s.delete(id,p.getUsername());}}
